/** Anything `cn` accepts: strings, falsy values (skipped), arrays, and `{ "class": condition }` objects. */
export type ClassValue = string | number | false | null | undefined | ClassValue[] | { [className: string]: unknown };

/** Join class names. Falsy values are skipped; arrays and `{ name: condition }` objects are flattened. */
export function cn(...parts: ClassValue[]): string {
  const out: string[] = [];
  for (const p of parts) {
    if (!p && p !== 0) continue;
    if (typeof p === "string" || typeof p === "number") out.push(String(p));
    else if (Array.isArray(p)) { const s = cn(...p); if (s) out.push(s); }
    else for (const [k, v] of Object.entries(p)) if (v) out.push(k);
  }
  return out.join(" ");
}

"use client";
import { useRef, type PointerEvent } from "react";

/** Where the pointer is, as fractions of the element, *not* clamped: below 0 or above 1 means it is past the edge (for rubber-banding). */
export interface DragRaw { x: number; y: number }

/** How fast the pointer was moving when it lifted, as fractions of the element per second (positive is right and down). */
export interface DragVelocity { vx: number; vy: number }

/**
 * Where something flicked from `pos` (0 to 1) with velocity `vel` (fractions per second) comes to rest. A flick carries on after the
 * finger lifts, the way a scroll view does: the distance is the sum of a decelerating glide. `rate` is how quickly it slows
 * (0.998 glides a long way, 0.99 a short one). The result is not clamped.
 */
export const project = (pos: number, vel: number, rate = 0.99) => pos + ((vel / 1000) * rate) / (1 - rate);

const WINDOW_MS = 90; // velocity is read from the last moments of the drag, not its whole length

/**
 * Pointer-capture drag over an element. `move` gets the pointer as 0 to 1 fractions of the element's box (clamped), and as a fourth
 * argument the same position unclamped (so a control can stretch when pulled past its end);
 * `end` fires on release with the last position and the velocity at the moment of release (use it with `project`
 * to let a flick carry on). Props go on the element itself.
 */
export function useDrag(
  move: (x: number, y: number, el: HTMLElement, raw: DragRaw) => void,
  end?: (x: number, y: number, el: HTMLElement, v: DragVelocity) => void,
) {
  const live = useRef(false);
  const last = useRef<[number, number]>([0, 0]);
  const raw = useRef<DragRaw>({ x: 0, y: 0 });
  const trail = useRef<{ t: number; x: number; y: number }[]>([]);
  const at = (e: PointerEvent<HTMLElement>): [number, number] => {
    const r = e.currentTarget.getBoundingClientRect();
    raw.current = { x: (e.clientX - r.left) / r.width, y: (e.clientY - r.top) / r.height };
    return [Math.min(1, Math.max(0, raw.current.x)), Math.min(1, Math.max(0, raw.current.y))];
  };
  const note = () => {
    const now = performance.now(), [x, y] = last.current;
    trail.current.push({ t: now, x, y });
    while (trail.current.length > 1 && now - trail.current[0].t > WINDOW_MS) trail.current.shift();
  };
  const velocity = (): DragVelocity => {
    const a = trail.current[0], b = trail.current[trail.current.length - 1];
    const dt = a && b ? b.t - a.t : 0;
    return dt > 8 ? { vx: ((b.x - a.x) / dt) * 1000, vy: ((b.y - a.y) / dt) * 1000 } : { vx: 0, vy: 0 };
  };
  return {
    onPointerDown: (e: PointerEvent<HTMLElement>) => { live.current = true; trail.current = []; e.currentTarget.setPointerCapture(e.pointerId); last.current = at(e); note(); move(...last.current, e.currentTarget, raw.current); },
    onPointerMove: (e: PointerEvent<HTMLElement>) => { if (!live.current) return; last.current = at(e); note(); move(...last.current, e.currentTarget, raw.current); },
    onPointerUp: (e: PointerEvent<HTMLElement>) => { if (!live.current) return; live.current = false; end?.(...last.current, e.currentTarget, velocity()); },
    onPointerCancel: () => { live.current = false; },
    "data-base-ui-swipe-ignore": true,
  } as const;
}

"use client";
import { useRef, type PointerEvent } from "react";

/**
 * Calls `onDouble` when the element is tapped twice quickly in the same place. A press that moved (a drag) is not a tap, so
 * dragging a control and then letting go never counts. Spread the result onto the element.
 */
export function useDoubleTap(onDouble: () => void, { within = 320, slop = 24 }: { within?: number; slop?: number } = {}) {
  const down = useRef<{ x: number; y: number } | null>(null);
  const last = useRef<{ t: number; x: number; y: number } | null>(null);
  return {
    onPointerDown: (e: PointerEvent<HTMLElement>) => { down.current = { x: e.clientX, y: e.clientY }; },
    onPointerUp: (e: PointerEvent<HTMLElement>) => {
      const d = down.current; down.current = null;
      if (!d || Math.hypot(e.clientX - d.x, e.clientY - d.y) > 10) { last.current = null; return; } // it moved: a drag, not a tap
      const now = performance.now(), l = last.current;
      if (l && now - l.t < within && Math.hypot(e.clientX - l.x, e.clientY - l.y) < slop) { last.current = null; onDouble(); }
      else last.current = { t: now, x: e.clientX, y: e.clientY };
    },
  };
}

"use client";
import { useRef, type MouseEvent, type PointerEvent } from "react";

/**
 * Lets a row of choices be swiped: put a finger on one and slide, and the choice under it is selected as it passes (like
 * an iOS segmented control). A plain tap still clicks. `itemSelector` finds the items inside the element the props go on.
 */
export function useSwipeSelect({ index, onIndex, itemSelector }: { index: number; onIndex: (i: number) => void; itemSelector: string }) {
  const press = useRef<{ id: number; x: number; moved: boolean } | null>(null);
  const swallow = useRef(false);
  return {
    onPointerDown: (e: PointerEvent<HTMLElement>) => { if (e.pointerType === "mouse" && e.button !== 0) return; if (e.currentTarget.scrollWidth > e.currentTarget.clientWidth + 1) return; /* it scrolls sideways: a swipe is a scroll */ press.current = { id: e.pointerId, x: e.clientX, moved: false }; },
    onPointerMove: (e: PointerEvent<HTMLElement>) => {
      const p = press.current; if (!p || e.pointerId !== p.id) return;
      if (!p.moved) { if (Math.abs(e.clientX - p.x) < 8) return; p.moved = true; try { e.currentTarget.setPointerCapture(e.pointerId); } catch { /* not capturable: the swipe still works while the pointer stays inside */ } }
      const items = [...e.currentTarget.querySelectorAll<HTMLElement>(itemSelector)];
      if (!items.length) return;
      const at = items.findIndex((el) => { const r = el.getBoundingClientRect(); return e.clientX >= r.left && e.clientX <= r.right; });
      const next = at >= 0 ? at : e.clientX < items[0].getBoundingClientRect().left ? 0 : items.length - 1;
      if (next !== index) onIndex(next);
    },
    onPointerUp: () => { if (press.current?.moved) { swallow.current = true; setTimeout(() => { swallow.current = false; }, 0); } press.current = null; },
    onPointerCancel: () => { press.current = null; },
    // the click that follows a swipe must not choose again
    onClickCapture: (e: MouseEvent<HTMLElement>) => { if (swallow.current) { e.stopPropagation(); e.preventDefault(); } },
  } as const;
}

/** Trusted in-app HTML (activity strings that carry bold). Never pass user input: it is not sanitised. */
export function Html({ html, as: T = "span" }: {
  /** Markup from the app itself. Never user input: it is not sanitised. */
  html: string;
  /** The element to render. */
  as?: "span" | "div" | "small";
}) {
  return <T data-slot="html" dangerouslySetInnerHTML={{ __html: html }} />;
}
